import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import os from 'node:os';import path from 'node:path';
import {DISMANTLE_GRANT_LIMIT,WORKBENCH_GRANT_LIMIT,Game} from '../server/game.js';import {makeWorld,generate,RUIN,VERSION,RECIPES,height,surface,blocked,placementError,sheltered} from '../shared/world.js';import {loadWorld,saveWorld} from '../server/persistence.js';
import {createSnapshotSession,nextSnapshotPacket} from '../server/snapshot-delta.js';
import {travel,tileAt,tileContent} from '../shared/planet.js';
import {floorHeight} from '../shared/build-grid.js';
function setup(){const g=new Game();const p=g.join('test-explorer','Ada');return{g,p};}
function gatherAll(g,p,type,count){for(const n of g.world.resources.filter(n=>n.type===type)){p.x=n.x;p.z=n.z;while(n.amount>0&&p.inventory[type]<count){g.tick(1);assert.equal(g.action(p.id,{type:'gather',id:n.id}).ok,true);}if(p.inventory[type]>=count)return;}}
function assertMalformedWorkbenchGrants(makeGrants){const{g,p}=setup(),q=g.join('other-explorer','Bo'),stored=makeGrants(g,p,q),bench={id:'bench',type:'workbench',x:0,z:3,owner:p.id,workbenchGrants:stored,workbenchQueue:[],workbenchNextSequence:0};q.inventory.meat=1;q.inventory.fiber=1;g.world.structures.push(bench);const before=structuredClone({inventory:q.inventory,queue:bench.workbenchQueue,nextSequence:bench.workbenchNextSequence,time:g.world.time,nextStructure:g.world.nextStructure,nextDrop:g.world.nextDrop});let result;assert.doesNotThrow(()=>{result=g.action(q.id,{type:'workbench',id:bench.id,recipe:'ration',sequence:0});});assert.deepEqual(result,{ok:false,message:'Only the workbench builder or an authorized collaborator may use it.'});let owner,collaborator;assert.doesNotThrow(()=>{owner=g.snapshot(p.id).structures[0];collaborator=g.snapshot(q.id).structures[0];});assert.deepEqual(owner.workbenchGrantedTo,[]);assert.equal(Object.hasOwn(collaborator,'canUseWorkbench'),false);for(const view of[owner,collaborator])assert.equal(Object.hasOwn(view,'workbenchGrants'),false);assert.deepEqual({inventory:q.inventory,queue:bench.workbenchQueue,nextSequence:bench.workbenchNextSequence,time:g.world.time,nextStructure:g.world.nextStructure,nextDrop:g.world.nextDrop},before);assert.equal(bench.workbenchGrants,stored);}
test('seeded terrain resources reproduce and vary with seed',()=>{assert.deepEqual(generate(17),generate(17));assert.notDeepEqual(generate(17),generate(18));});
test('Deck stair is available in the accessible construction palette with a rendered ramp',()=>{const client=fs.readFileSync(new URL('../client/main.js',import.meta.url),'utf8');assert.deepEqual(RECIPES.stairs,{name:'Deck stair',cost:{ferrite:2,fiber:1},description:'A low-rise stair from terrain to one supported deck edge. R rotates to another edge.'});assert.match(client,/const pieces=\[[^\n]*'stairs'/);assert.match(client,/piece\.type==='stairs'/);});
test('Workbench is available through the existing construction and accessible render paths',()=>{const client=fs.readFileSync(new URL('../client/main.js',import.meta.url),'utf8');assert.deepEqual(RECIPES.workbench,{name:'Workbench',cost:{ferrite:6,fiber:2},description:'A nearby fabrication station with one active job and two pending jobs.'});assert.match(client,/const pieces=\[[^\n]*'workbench'/);assert.match(client,/materials=\{[^\n]*workbench:/);const{g,p}=setup();p.x=9;p.z=4.5;p.inventory.ferrite=10;p.inventory.fiber=10;g.world.resources=[];const result=g.action(p.id,{type:'build',piece:'workbench',x:9,z:0,rotation:0});assert.deepEqual(result,{ok:true,message:'Workbench constructed.'});assert.deepEqual(g.world.structures.at(-1),{type:'workbench',x:9,z:0,rotation:0,health:200,id:'s1',owner:p.id,workbenchQueue:[],workbenchNextSequence:0});});
test('nearby owner enqueues one field meal with inputs reserved exactly once',()=>{const{g,p}=setup();p.inventory.meat=1;p.inventory.fiber=1;g.world.structures.push({id:'bench',type:'workbench',x:0,z:3,rotation:0,health:200,owner:p.id,workbenchQueue:[],workbenchNextSequence:0});const result=g.action(p.id,{type:'workbench',id:'bench',recipe:'ration',sequence:0});assert.deepEqual(result,{ok:true,message:'Field meal queued.'});assert.equal(p.inventory.meat,0);assert.equal(p.inventory.fiber,0);assert.deepEqual(g.world.structures[0].workbenchQueue,[{id:'workbench-0',owner:p.id,recipe:'ration',state:'in-progress',startedAt:0}]);assert.equal(g.world.structures[0].workbenchNextSequence,1);});
test('nearby player cancels one own pending field meal with exact refund once',()=>{const{g,p}=setup(),q=g.join('other-explorer','Bo'),bench={id:'bench',type:'workbench',x:0,z:3,owner:p.id,workbenchGrants:[q.id],workbenchQueue:[],workbenchNextSequence:0};p.inventory.meat=1;p.inventory.fiber=1;q.inventory.meat=1;q.inventory.fiber=1;g.world.structures.push(bench);assert.equal(g.action(p.id,{type:'workbench',id:bench.id,recipe:'ration',sequence:0}).ok,true);assert.equal(g.action(q.id,{type:'workbench',id:bench.id,recipe:'ration',sequence:1}).ok,true);assert.deepEqual(g.action(q.id,{type:'workbenchCancel',id:bench.id,jobId:'workbench-1'}),{ok:true,message:'Pending Field meal cancelled. Ingredients returned.'});assert.equal(q.inventory.meat,1);assert.equal(q.inventory.fiber,1);assert.deepEqual(bench.workbenchQueue,[{id:'workbench-0',owner:p.id,recipe:'ration',state:'in-progress',startedAt:0}]);const after=structuredClone({inventory:q.inventory,queue:bench.workbenchQueue,nextSequence:bench.workbenchNextSequence});assert.equal(g.action(q.id,{type:'workbenchCancel',id:bench.id,jobId:'workbench-1'}).ok,false);assert.deepEqual({inventory:q.inventory,queue:bench.workbenchQueue,nextSequence:bench.workbenchNextSequence},after);});
test('pending cancellation fails closed for a non-writable workbench queue property',()=>{const{g,p}=setup(),q=g.join('other-explorer','Bo'),bench={id:'bench',type:'workbench',x:0,z:3,owner:p.id,workbenchGrants:[q.id],workbenchQueue:[{id:'workbench-0',owner:p.id,recipe:'ration',state:'in-progress',startedAt:0},{id:'workbench-1',owner:q.id,recipe:'ration',state:'queued'}],workbenchNextSequence:2};g.world.structures.push(bench);Object.defineProperty(bench,'workbenchQueue',{value:bench.workbenchQueue,enumerable:true,writable:false,configurable:true});const before=structuredClone({inventory:q.inventory,queue:bench.workbenchQueue,nextSequence:bench.workbenchNextSequence,time:g.world.time,cooldowns:[...g.cooldowns]});let result;assert.doesNotThrow(()=>{result=g.action(q.id,{type:'workbenchCancel',id:bench.id,jobId:'workbench-1'});});assert.deepEqual(result,{ok:false,message:'Invalid workbench queue state.'});assert.deepEqual({inventory:q.inventory,queue:bench.workbenchQueue,nextSequence:bench.workbenchNextSequence,time:g.world.time,cooldowns:[...g.cooldowns]},before);});
test('pending cancellation rejects a Proxy Workbench without invoking its set trap or mutating state',()=>{const{g,p}=setup(),q=g.join('other-explorer','Bo'),queue=[{id:'workbench-0',owner:p.id,recipe:'ration',state:'in-progress',startedAt:0},{id:'workbench-1',owner:q.id,recipe:'ration',state:'queued'}],stored={id:'bench',type:'workbench',x:0,z:3,owner:p.id,workbenchGrants:[q.id],workbenchQueue:queue,workbenchNextSequence:2};let setCalls=0;const bench=new Proxy(stored,{set(){setCalls++;throw new Error('set sentinel');}});g.world.structures.push(bench);const inventoryBefore=Object.getOwnPropertyDescriptors(q.inventory),stateBefore=structuredClone({queue,nextSequence:stored.workbenchNextSequence,time:g.world.time,cooldowns:[...g.cooldowns]});let result;assert.doesNotThrow(()=>{result=g.action(q.id,{type:'workbenchCancel',id:'bench',jobId:'workbench-1'});});assert.equal(setCalls,0);assert.deepEqual(result,{ok:false,message:'Move within 3 m of the exact workbench.'});assert.deepEqual(Object.getOwnPropertyDescriptors(q.inventory),inventoryBefore);assert.deepEqual({queue,nextSequence:stored.workbenchNextSequence,time:g.world.time,cooldowns:[...g.cooldowns]},stateBefore);});
test('pending cancellation rejects an accessor Workbench id without executing its getter or mutating state',()=>{const{g,p}=setup(),q=g.join('other-explorer','Bo'),queue=[{id:'workbench-0',owner:p.id,recipe:'ration',state:'in-progress',startedAt:0},{id:'workbench-1',owner:q.id,recipe:'ration',state:'queued'}],bench={type:'workbench',x:0,z:3,owner:p.id,workbenchGrants:[q.id],workbenchQueue:queue,workbenchNextSequence:2};let getterCalls=0;Object.defineProperty(bench,'id',{get(){getterCalls++;throw new Error('id getter sentinel');},enumerable:true,configurable:true});g.world.structures.push(bench);const inventoryBefore=Object.getOwnPropertyDescriptors(q.inventory),stateBefore=structuredClone({queue,nextSequence:bench.workbenchNextSequence,time:g.world.time,cooldowns:[...g.cooldowns]});let result;assert.doesNotThrow(()=>{result=g.action(q.id,{type:'workbenchCancel',id:'bench',jobId:'workbench-1'});});assert.equal(getterCalls,0);assert.deepEqual(result,{ok:false,message:'Move within 3 m of the exact workbench.'});assert.deepEqual(Object.getOwnPropertyDescriptors(q.inventory),inventoryBefore);assert.deepEqual({queue,nextSequence:bench.workbenchNextSequence,time:g.world.time,cooldowns:[...g.cooldowns]},stateBefore);});
test('pending cancellation fails closed before a non-writable refund destination mutates state',()=>{for(const item of['meat','fiber']){const{g,p}=setup(),q=g.join('other-explorer','Bo'),bench={id:'bench',type:'workbench',x:0,z:3,owner:p.id,workbenchGrants:[q.id],workbenchQueue:[{id:'workbench-0',owner:p.id,recipe:'ration',state:'in-progress',startedAt:0},{id:'workbench-1',owner:q.id,recipe:'ration',state:'queued'}],workbenchNextSequence:2};g.world.structures.push(bench);Object.defineProperty(q.inventory,item,{value:0,enumerable:true,writable:false,configurable:true});const before=structuredClone({inventory:q.inventory,queue:bench.workbenchQueue,nextSequence:bench.workbenchNextSequence,time:g.world.time,cooldowns:[...g.cooldowns]});let result;assert.doesNotThrow(()=>{result=g.action(q.id,{type:'workbenchCancel',id:bench.id,jobId:'workbench-1'});});assert.deepEqual(result,{ok:false,message:'Invalid inventory state.'});assert.deepEqual({inventory:q.inventory,queue:bench.workbenchQueue,nextSequence:bench.workbenchNextSequence,time:g.world.time,cooldowns:[...g.cooldowns]},before);}});
test('pending cancellation rejects an unrelated inventory accessor without executing it or mutating state',()=>{const{g,p}=setup(),q=g.join('other-explorer','Bo'),bench={id:'bench',type:'workbench',x:0,z:3,owner:p.id,workbenchGrants:[q.id],workbenchQueue:[{id:'workbench-0',owner:p.id,recipe:'ration',state:'in-progress',startedAt:0},{id:'workbench-1',owner:q.id,recipe:'ration',state:'queued'}],workbenchNextSequence:2};g.world.structures.push(bench);let getterCalls=0;Object.defineProperty(q.inventory,'ferrite',{get(){getterCalls++;throw new Error('inventory getter executed');},enumerable:true,configurable:true});const inventoryBefore=Object.getOwnPropertyDescriptors(q.inventory),stateBefore=structuredClone({queue:bench.workbenchQueue,nextSequence:bench.workbenchNextSequence,time:g.world.time,cooldowns:[...g.cooldowns]});let result;assert.doesNotThrow(()=>{result=g.action(q.id,{type:'workbenchCancel',id:bench.id,jobId:'workbench-1'});});assert.equal(getterCalls,0);assert.deepEqual(result,{ok:false,message:'Invalid inventory state.'});assert.deepEqual(Object.getOwnPropertyDescriptors(q.inventory),inventoryBefore);assert.deepEqual({queue:bench.workbenchQueue,nextSequence:bench.workbenchNextSequence,time:g.world.time,cooldowns:[...g.cooldowns]},stateBefore);});
test('malformed workbench queue descriptors fail closed without cancellation or completion mutation',()=>{for(const descriptor of[{enumerable:false,writable:true,configurable:true},{enumerable:true,writable:true,configurable:false},'accessor']){const{g,p}=setup(),q=g.join('other-explorer','Bo'),queue=[{id:'workbench-0',owner:p.id,recipe:'ration',state:'in-progress',startedAt:0},{id:'workbench-1',owner:q.id,recipe:'ration',state:'queued'}],bench={id:'bench',type:'workbench',x:0,z:3,owner:p.id,workbenchGrants:[q.id],workbenchQueue:queue,workbenchNextSequence:2};g.world.structures.push(bench);let getterCalls=0;if(descriptor==='accessor')Object.defineProperty(bench,'workbenchQueue',{get(){getterCalls++;return queue;},enumerable:true,configurable:true});else Object.defineProperty(bench,'workbenchQueue',{value:queue,...descriptor});const before=structuredClone({inventory:q.inventory,queue,nextSequence:bench.workbenchNextSequence,time:g.world.time,cooldowns:[...g.cooldowns]});let result;assert.doesNotThrow(()=>{result=g.action(q.id,{type:'workbenchCancel',id:bench.id,jobId:'workbench-1'});});assert.deepEqual(result,{ok:false,message:'Invalid workbench queue state.'});assert.equal(getterCalls,0);assert.deepEqual({inventory:q.inventory,queue,nextSequence:bench.workbenchNextSequence,time:g.world.time,cooldowns:[...g.cooldowns]},before);}const{g,p}=setup(),queue=[{id:'workbench-0',owner:p.id,recipe:'ration',state:'blocked-output',startedAt:0}],bench={id:'bench',type:'workbench',x:0,z:3,owner:p.id,workbenchQueue:queue,workbenchNextSequence:1};g.world.time=5;g.world.structures.push(bench);Object.defineProperty(queue,'length',{writable:false});const before=structuredClone({inventory:p.inventory,queue,nextSequence:bench.workbenchNextSequence,time:g.world.time,cooldowns:[...g.cooldowns]});assert.doesNotThrow(()=>g.tick(0));assert.deepEqual({inventory:p.inventory,queue,nextSequence:bench.workbenchNextSequence,time:g.world.time,cooldowns:[...g.cooldowns]},before);});
test('pending cancellation preserves remaining order active timing and monotonic workbench sequence',()=>{const{g,p}=setup(),bench={id:'bench',type:'workbench',x:0,z:3,owner:p.id,workbenchQueue:[],workbenchNextSequence:0};p.inventory.meat=4;p.inventory.fiber=4;g.world.structures.push(bench);for(let sequence=0;sequence<3;sequence++)assert.equal(g.action(p.id,{type:'workbench',id:bench.id,recipe:'ration',sequence}).ok,true);g.tick(2);const startedAt=bench.workbenchQueue[0].startedAt;assert.equal(g.action(p.id,{type:'workbenchCancel',id:bench.id,jobId:'workbench-1'}).ok,true);assert.deepEqual(bench.workbenchQueue.map(job=>job.id),['workbench-0','workbench-2']);assert.equal(bench.workbenchQueue[0].startedAt,startedAt);assert.equal(bench.workbenchNextSequence,3);assert.equal(g.action(p.id,{type:'workbench',id:bench.id,recipe:'ration',sequence:3}).ok,true);assert.deepEqual(bench.workbenchQueue.map(job=>job.id),['workbench-0','workbench-2','workbench-3']);assert.equal(bench.workbenchNextSequence,4);});
test('active blocked foreign remote malformed stale and unsafe pending cancellations fail closed',()=>{const{g,p}=setup(),q=g.join('other-explorer','Bo'),bench={id:'bench',type:'workbench',x:0,z:3,owner:p.id,workbenchGrants:[q.id],workbenchQueue:[],workbenchNextSequence:0};p.inventory.meat=1;p.inventory.fiber=1;q.inventory.meat=1;q.inventory.fiber=1;g.world.structures.push(bench);assert.equal(g.action(p.id,{type:'workbench',id:bench.id,recipe:'ration',sequence:0}).ok,true);assert.equal(g.action(q.id,{type:'workbench',id:bench.id,recipe:'ration',sequence:1}).ok,true);const reject=(actor,request)=>{const before=structuredClone(g.world);assert.equal(g.action(actor.id,request).ok,false);assert.deepEqual(g.world,before);};reject(p,{type:'workbenchCancel',id:bench.id,jobId:'workbench-0'});reject(p,{type:'workbenchCancel',id:bench.id,jobId:'workbench-1'});reject(q,{type:'workbenchCancel',id:'wrong-bench',jobId:'workbench-1'});reject(q,{type:'workbenchCancel',id:bench.id,jobId:'workbench-99'});reject(q,{type:'workbenchCancel',id:bench.id,jobId:'workbench-1',extra:true});q.x=20;reject(q,{type:'workbenchCancel',id:bench.id,jobId:'workbench-1'});q.x=0;p.inventory.ferrite=60;g.tick(5);reject(p,{type:'workbenchCancel',id:bench.id,jobId:'workbench-0'});let traps=0;const stored=bench.workbenchQueue;bench.workbenchQueue=new Proxy(stored,{get(){traps++;throw new Error('queue trap executed');},getPrototypeOf(){traps++;throw new Error('queue trap executed');}});let result;assert.doesNotThrow(()=>{result=g.action(q.id,{type:'workbenchCancel',id:bench.id,jobId:'workbench-1'});});assert.equal(result.ok,false);assert.equal(traps,0);});
test('pending cancellation rejects an over-cap refund without partial mutation',()=>{const{g,p}=setup(),q=g.join('other-explorer','Bo'),bench={id:'bench',type:'workbench',x:0,z:3,owner:p.id,workbenchGrants:[q.id],workbenchQueue:[],workbenchNextSequence:0};p.inventory.meat=1;p.inventory.fiber=1;q.inventory.meat=1;q.inventory.fiber=1;g.world.structures.push(bench);assert.equal(g.action(p.id,{type:'workbench',id:bench.id,recipe:'ration',sequence:0}).ok,true);assert.equal(g.action(q.id,{type:'workbench',id:bench.id,recipe:'ration',sequence:1}).ok,true);q.inventory.ferrite=59;const before=structuredClone({inventory:q.inventory,queue:bench.workbenchQueue,nextSequence:bench.workbenchNextSequence});assert.deepEqual(g.action(q.id,{type:'workbenchCancel',id:bench.id,jobId:'workbench-1'}),{ok:false,message:'Make room for the returned ingredients.'});assert.deepEqual({inventory:q.inventory,queue:bench.workbenchQueue,nextSequence:bench.workbenchNextSequence},before);q.inventory.ferrite=58;assert.equal(g.action(q.id,{type:'workbenchCancel',id:bench.id,jobId:'workbench-1'}).ok,true);assert.equal(q.inventory.ferrite+q.inventory.meat+q.inventory.fiber,60);});
test('nearby workbench owner grants one saved collaborator use permission',()=>{const{g,p}=setup(),q=g.join('other-explorer','Bo'),bench={id:'bench',type:'workbench',x:0,z:3,owner:p.id,workbenchQueue:[],workbenchNextSequence:0};g.world.structures.push(bench);assert.equal(WORKBENCH_GRANT_LIMIT,32);assert.deepEqual(g.action(p.id,{type:'workbenchAccess',id:bench.id,target:q.id,allow:true}),{ok:true,message:'Bo may use this workbench.'});assert.deepEqual(bench.workbenchGrants,[q.id]);});
test('authorized collaborator queues with own ingredients and receives own output',()=>{const{g,p}=setup(),q=g.join('other-explorer','Bo'),bench={id:'bench',type:'workbench',x:0,z:3,owner:p.id,workbenchGrants:[q.id],workbenchQueue:[],workbenchNextSequence:0};q.inventory.meat=1;q.inventory.fiber=1;g.world.structures.push(bench);assert.equal(g.action(q.id,{type:'workbench',id:bench.id,recipe:'ration',sequence:0}).ok,true);assert.equal(q.inventory.meat,0);assert.equal(q.inventory.fiber,0);assert.equal(p.inventory.ration,0);assert.equal(bench.workbenchQueue[0].owner,q.id);g.tick(5);assert.equal(q.inventory.ration,1);assert.equal(p.inventory.ration,0);assert.deepEqual(bench.workbenchQueue,[]);});
test('workbench revocation denies the next collaborator action and strangers remain denied',()=>{const{g,p}=setup(),q=g.join('other-explorer','Bo'),r=g.join('third-explorer','Cy'),bench={id:'bench',type:'workbench',x:0,z:3,owner:p.id,workbenchGrants:[q.id],workbenchQueue:[],workbenchNextSequence:0};for(const actor of[q,r]){actor.inventory.meat=1;actor.inventory.fiber=1;}g.world.structures.push(bench);assert.deepEqual(g.action(p.id,{type:'workbenchAccess',id:bench.id,target:q.id,allow:false}),{ok:true,message:'Bo no longer has workbench access.'});assert.equal(Object.hasOwn(bench,'workbenchGrants'),false);for(const actor of[q,r]){const before=structuredClone(actor.inventory);assert.equal(g.action(actor.id,{type:'workbench',id:bench.id,recipe:'ration',sequence:0}).ok,false);assert.deepEqual(actor.inventory,before);}assert.deepEqual(bench.workbenchQueue,[]);});
test('malformed persisted workbench grants fail closed without revealing rejected values',()=>{const malformed=[null,{},['other-explorer','other-explorer'],['test-explorer'],['missing-explorer'],['__proto__'],[7],['x'.repeat(129)],Array.from({length:WORKBENCH_GRANT_LIMIT+1},()=> 'other-explorer')];for(const stored of malformed){const{g,p}=setup(),q=g.join('other-explorer','Bo'),bench={id:'bench',type:'workbench',x:0,z:3,owner:p.id,workbenchGrants:stored,workbenchQueue:[],workbenchNextSequence:0};q.inventory.meat=1;q.inventory.fiber=1;g.world.structures.push(bench);assert.equal(g.action(q.id,{type:'workbench',id:bench.id,recipe:'ration',sequence:0}).ok,false);const owner=g.snapshot(p.id).structures[0],collaborator=g.snapshot(q.id).structures[0];assert.deepEqual(owner.workbenchGrantedTo,[]);for(const view of[owner,collaborator])assert.equal(Object.hasOwn(view,'workbenchGrants'),false);}});
test('sparse persisted workbench grant containing the collaborator fails closed without mutation',()=>{const{g,p}=setup(),q=g.join('other-explorer','Bo'),grants=new Array(2),bench={id:'bench',type:'workbench',x:0,z:3,owner:p.id,workbenchGrants:grants,workbenchQueue:[],workbenchNextSequence:0};grants[0]=q.id;q.inventory.meat=1;q.inventory.fiber=1;g.world.structures.push(bench);const before=Buffer.from(JSON.stringify({world:g.world,cooldowns:[...g.cooldowns]}));assert.deepEqual(g.action(q.id,{type:'workbench',id:bench.id,recipe:'ration',sequence:0}),{ok:false,message:'Only the workbench builder or an authorized collaborator may use it.'});assert.deepEqual(Buffer.from(JSON.stringify({world:g.world,cooldowns:[...g.cooldowns]})),before);});
test('hole-only persisted workbench grants fail closed without mutation or projection',()=>{assertMalformedWorkbenchGrants(()=>new Array(1));});
test('Proxy persisted workbench grants fail closed without executing a trap',()=>{let traps=0;assertMalformedWorkbenchGrants((g,p,q)=>new Proxy([q.id],{get(){traps++;throw new Error('get trap executed');},getOwnPropertyDescriptor(){traps++;throw new Error('descriptor trap executed');},getPrototypeOf(){traps++;throw new Error('prototype trap executed');},ownKeys(){traps++;throw new Error('ownKeys trap executed');}}));assert.equal(traps,0);});
test('custom-prototype persisted workbench grants fail closed without mutation or projection',()=>{assertMalformedWorkbenchGrants((g,p,q)=>Object.setPrototypeOf([q.id],Object.create(Array.prototype)));});
test('accessor persisted workbench grants fail closed without executing its getter',()=>{let getters=0;assertMalformedWorkbenchGrants((g,p,q)=>{const grants=[q.id];Object.defineProperty(grants,0,{get(){getters++;return q.id;},enumerable:true,configurable:true});return grants;});assert.equal(getters,0);});
test('extra-descriptor persisted workbench grants fail closed without mutation or projection',()=>{assertMalformedWorkbenchGrants((g,p,q)=>Object.assign([q.id],{metadata:'unexpected'}));});
test('non-ordinary persisted workbench grant descriptors fail closed without mutation or projection',()=>{assertMalformedWorkbenchGrants((g,p,q)=>{const grants=[q.id];Object.defineProperty(grants,0,{value:q.id,enumerable:true,writable:false,configurable:true});return grants;});});
test('duplicate persisted workbench grants fail closed without mutation or projection',()=>{assertMalformedWorkbenchGrants((g,p,q)=>[q.id,q.id]);});
test('special-key persisted workbench grants fail closed without mutation or projection',()=>{assertMalformedWorkbenchGrants((g,p)=>{Object.defineProperty(g.world.players,'__proto__',{value:{...p,id:'__proto__',name:'Unsafe'},enumerable:true,writable:true,configurable:true});return['__proto__'];});});
test('unknown-player persisted workbench grants fail closed without mutation or projection',()=>{assertMalformedWorkbenchGrants(()=>['missing-explorer']);});
test('non-string persisted workbench grants fail closed without mutation or projection',()=>{assertMalformedWorkbenchGrants(()=>[7]);});
test('over-length persisted workbench grant values fail closed without mutation or projection',()=>{assertMalformedWorkbenchGrants(()=>['x'.repeat(129)]);});
test('over-cap persisted workbench grants fail closed without mutation or projection',()=>{assertMalformedWorkbenchGrants((g,p,q)=>Array.from({length:WORKBENCH_GRANT_LIMIT+1},(_,index)=>index?q.id+index:q.id).map((id,index)=>index?g.join(id,`Saved ${index}`).id:id));});
test('self persisted workbench grants fail closed without mutation or projection',()=>{assertMalformedWorkbenchGrants((g,p)=>[p.id]);});
test('workbench projections give owner roster collaborator use flag and no stranger private state',()=>{const{g,p}=setup(),q=g.join('other-explorer','Bo'),r=g.join('third-explorer','Cy'),bench={id:'bench',type:'workbench',x:0,z:3,owner:p.id,workbenchGrants:[q.id],workbenchQueue:[{id:'workbench-0',owner:q.id,recipe:'ration',state:'in-progress',startedAt:0}],workbenchNextSequence:1};g.world.structures.push(bench);const owner=g.snapshot(p.id).structures[0],collaborator=g.snapshot(q.id).structures[0],stranger=g.snapshot(r.id).structures[0],publicView=g.snapshot().structures[0];assert.deepEqual(owner.workbenchGrantedTo,[{id:q.id,name:q.name}]);assert.equal(collaborator.canUseWorkbench,true);assert.deepEqual({water:collaborator.water,power:collaborator.power,readyAt:collaborator.readyAt,cycleUntil:collaborator.cycleUntil},{water:1,power:0,readyAt:5,cycleUntil:1});for(const view of[collaborator,stranger,publicView])assert.equal(Object.hasOwn(view,'workbenchGrantedTo'),false);for(const view of[stranger,publicView])for(const key of['canUseWorkbench','water','power','readyAt','cycleUntil'])assert.equal(Object.hasOwn(view,key),false);for(const view of[owner,collaborator,stranger,publicView])for(const key of['workbenchGrants','workbenchQueue','workbenchNextSequence'])assert.equal(Object.hasOwn(view,key),false);});
test('workbench projection exposes only each viewer earliest cancellable pending job',()=>{const{g,p}=setup(),q=g.join('other-explorer','Bo'),r=g.join('third-explorer','Cy'),bench={id:'bench',type:'workbench',x:0,z:3,owner:p.id,workbenchGrants:[q.id],workbenchQueue:[{id:'workbench-0',owner:p.id,recipe:'ration',state:'in-progress',startedAt:0},{id:'workbench-1',owner:q.id,recipe:'ration',state:'queued'},{id:'workbench-2',owner:p.id,recipe:'ration',state:'queued'}],workbenchNextSequence:3},pick=({canCancelWorkbench,workbenchCancelJobId})=>({canCancelWorkbench,workbenchCancelJobId});g.world.structures.push(bench);assert.deepEqual(pick(g.snapshot(q.id).structures[0]),{canCancelWorkbench:true,workbenchCancelJobId:'workbench-1'});assert.deepEqual(pick(g.snapshot(p.id).structures[0]),{canCancelWorkbench:true,workbenchCancelJobId:'workbench-2'});for(const view of[g.snapshot(r.id).structures[0],g.snapshot().structures[0]])for(const key of['canCancelWorkbench','workbenchCancelJobId'])assert.equal(Object.hasOwn(view,key),false);for(const view of[g.snapshot(p.id).structures[0],g.snapshot(q.id).structures[0]])for(const key of['workbenchQueue','workbenchNextSequence','workbenchJobOwner','workbenchIngredients'])assert.equal(Object.hasOwn(view,key),false);});
test('field meals cannot bypass the server-owned workbench queue',()=>{const{g,p}=setup();p.inventory.meat=1;p.inventory.fiber=1;const before=structuredClone(g.world);assert.deepEqual(g.action(p.id,{type:'craft',recipe:'ration'}),{ok:false,message:'Prepare field meals at a nearby workbench.'});assert.deepEqual(g.world,before);});
test('authoritative workbench progress grants one result exactly once after five game seconds',()=>{const{g,p}=setup();p.inventory.meat=1;p.inventory.fiber=1;g.world.structures.push({id:'bench',type:'workbench',x:0,z:3,rotation:0,health:200,owner:p.id,workbenchQueue:[],workbenchNextSequence:0});assert.equal(g.action(p.id,{type:'workbench',id:'bench',recipe:'ration',sequence:0}).ok,true);g.tick(4.99);assert.equal(p.inventory.ration,0);assert.equal(g.world.structures[0].workbenchQueue[0].state,'in-progress');g.tick(.01);assert.equal(p.inventory.ration,1);assert.deepEqual(g.world.structures[0].workbenchQueue,[]);g.tick(20);assert.equal(p.inventory.ration,1);});
test('workbench completion fails closed before a non-writable ration destination mutates state',()=>{const{g,p}=setup(),bench={id:'bench',type:'workbench',x:0,z:3,rotation:0,health:200,owner:p.id,workbenchQueue:[{id:'workbench-0',owner:p.id,recipe:'ration',state:'in-progress',startedAt:0}],workbenchNextSequence:1};g.world.time=5;g.world.structures.push(bench);Object.defineProperty(p.inventory,'ration',{value:0,enumerable:true,writable:false,configurable:true});const before=structuredClone({inventory:p.inventory,queue:bench.workbenchQueue,nextSequence:bench.workbenchNextSequence,time:g.world.time,cooldowns:[...g.cooldowns]});assert.doesNotThrow(()=>g.tick(0));assert.deepEqual({inventory:p.inventory,queue:bench.workbenchQueue,nextSequence:bench.workbenchNextSequence,time:g.world.time,cooldowns:[...g.cooldowns]},before);});
test('workbench completion rejects an unrelated inventory accessor without executing it or mutating state',()=>{const{g,p}=setup(),bench={id:'bench',type:'workbench',x:0,z:3,rotation:0,health:200,owner:p.id,workbenchQueue:[{id:'workbench-0',owner:p.id,recipe:'ration',state:'in-progress',startedAt:0}],workbenchNextSequence:1};g.world.time=5;g.world.structures.push(bench);let getterCalls=0;Object.defineProperty(p.inventory,'ferrite',{get(){getterCalls++;throw new Error('inventory getter executed');},enumerable:true,configurable:true});const inventoryBefore=Object.getOwnPropertyDescriptors(p.inventory),stateBefore=structuredClone({queue:bench.workbenchQueue,nextSequence:bench.workbenchNextSequence,time:g.world.time,cooldowns:[...g.cooldowns]});assert.doesNotThrow(()=>g.tick(0));assert.equal(getterCalls,0);assert.deepEqual(Object.getOwnPropertyDescriptors(p.inventory),inventoryBefore);assert.deepEqual({queue:bench.workbenchQueue,nextSequence:bench.workbenchNextSequence,time:g.world.time,cooldowns:[...g.cooldowns]},stateBefore);});
test('malformed stale duplicate skipped and unsafe workbench sequences fail without mutation',()=>{const{g,p}=setup();p.inventory.meat=4;p.inventory.fiber=4;const bench={id:'bench',type:'workbench',x:0,z:3,rotation:0,owner:p.id,workbenchQueue:[],workbenchNextSequence:1};g.world.structures.push(bench);for(const sequence of[0,2,-1,1.5,Number.MAX_SAFE_INTEGER,Number.MAX_SAFE_INTEGER+1,Infinity,'1',undefined]){const before=structuredClone(g.world),cooldowns=structuredClone([...g.cooldowns]);assert.equal(g.action(p.id,{type:'workbench',id:'bench',recipe:'ration',sequence}).ok,false);assert.deepEqual(g.world,before);assert.deepEqual([...g.cooldowns],cooldowns);}});
test('malformed persisted workbench queue fails closed without mutation crash or projection',()=>{const{g,p}=setup();p.inventory.meat=1;p.inventory.fiber=1;g.world.structures.push({id:'bench',type:'workbench',x:0,z:3,rotation:0,owner:p.id,workbenchQueue:[null],workbenchNextSequence:0});const before=structuredClone(g.world),cooldowns=structuredClone([...g.cooldowns]);assert.deepEqual(g.action(p.id,{type:'workbench',id:'bench',recipe:'ration',sequence:0}),{ok:false,message:'Invalid workbench queue state.'});assert.deepEqual(g.world,before);assert.deepEqual([...g.cooldowns],cooldowns);assert.doesNotThrow(()=>g.tick(.1));let owner;assert.doesNotThrow(()=>{owner=g.snapshot(p.id).structures[0];});assert.equal(Object.hasOwn(owner,'water'),false);assert.equal(Object.hasOwn(owner,'power'),false);assert.equal(Object.hasOwn(owner,'readyAt'),false);});
test('workbench snapshots expose bounded queue and next-sequence meaning only to its owner',()=>{const{g,p}=setup(),q=g.join('other-explorer','Bo');p.inventory.meat=1;p.inventory.fiber=1;g.world.structures.push({id:'bench',type:'workbench',x:0,z:3,rotation:0,owner:p.id,workbenchQueue:[],workbenchNextSequence:0});assert.equal(g.action(p.id,{type:'workbench',id:'bench',recipe:'ration',sequence:0}).ok,true);const owner=g.snapshot(p.id).structures[0],stranger=g.snapshot(q.id).structures[0];assert.deepEqual({power:owner.power,water:owner.water,readyAt:owner.readyAt,nextSequence:owner.cycleUntil},{power:0,water:1,readyAt:5,nextSequence:1});for(const view of[owner,stranger])for(const key of['workbenchQueue','workbenchRequests','workbenchNextSequence'])assert.equal(Object.hasOwn(view,key),false);for(const key of['power','water','readyAt','cycleUntil'])assert.equal(Object.hasOwn(stranger,key),false);assert.doesNotThrow(()=>createSnapshotSession(g.snapshot(p.id)));});
test('Field Guide queues meals at a nearby authorized workbench and reports authoritative queue states',()=>{const client=fs.readFileSync(new URL('../client/main.js',import.meta.url),'utf8');assert.match(client,/type:'workbench',id:bench\.id,recipe:'ration',sequence:bench\.cycleUntil/);assert.match(client,/Move within 3 m of a workbench you may use/);assert.match(client,/QUEUE FULL/);assert.match(client,/BLOCKED · MAKE BACKPACK SPACE/);assert.match(client,/IN PROGRESS/);assert.match(client,/Ready · 5 server seconds/);});
test('full output blocks losslessly and active work denies dismantling until delivered',()=>{const{g,p}=setup();p.inventory.meat=1;p.inventory.fiber=1;g.world.structures.push({id:'bench',type:'workbench',x:0,z:3,rotation:0,health:200,owner:p.id,workbenchQueue:[],workbenchNextSequence:0});assert.equal(g.action(p.id,{type:'workbench',id:'bench',recipe:'ration',sequence:0}).ok,true);p.inventory.ferrite=60;g.tick(5);assert.equal(p.inventory.ration,0);assert.equal(g.world.structures[0].workbenchQueue[0].state,'blocked-output');const before=structuredClone(g.world);assert.match(g.action(p.id,{type:'dismantle',id:'bench'}).message,/queue/i);assert.deepEqual(g.world,before);p.inventory.ferrite--;g.tick(.01);assert.equal(p.inventory.ration,1);assert.deepEqual(g.world.structures[0].workbenchQueue,[]);});
test('workbench rejection paths preserve inventory queue replay state time and cooldown',()=>{const attempt=(prepare,message,expected)=>{const{g,p}=setup();p.inventory.meat=4;p.inventory.fiber=4;const bench={id:'bench',type:'workbench',x:0,z:3,rotation:0,owner:p.id,workbenchQueue:[],workbenchNextSequence:0};g.world.structures.push(bench);const request={type:'workbench',id:'bench',recipe:'ration',sequence:0,...message};prepare(g,p,bench,request);const before=structuredClone(g.world),cooldowns=structuredClone([...g.cooldowns]);assert.match(g.action(p.id,request).message,expected);assert.deepEqual(g.world,before);assert.deepEqual([...g.cooldowns],cooldowns);};attempt(()=>{},{extra:true},/Invalid/);attempt((g,p,b,r)=>r.recipe='cutter',{},/Invalid/);attempt((g,p,b,r)=>r.id='missing',{},/within 3 m/);attempt((g,p)=>p.x=20,{},/within 3 m/);attempt((g,p,b)=>b.owner='other',{},/builder/);attempt((g,p)=>{p.inventory.meat=0;},{},/ingredients/);attempt((g,p,b,r)=>{b.workbenchQueue=[{id:'workbench-0',owner:p.id,recipe:'ration',state:'in-progress',startedAt:0},{id:'workbench-1',owner:p.id,recipe:'ration',state:'queued'},{id:'workbench-2',owner:p.id,recipe:'ration',state:'queued'}];b.workbenchNextSequence=3;r.sequence=3;},{},/full/);attempt((g,p,b,r)=>{b.workbenchNextSequence=1;r.sequence=0;},{},/stale or skipped/);attempt((g,p,b,r)=>{b.workbenchNextSequence=0;r.sequence=1;},{},/stale or skipped/);attempt((g,p,b)=>{delete b.workbenchNextSequence;b.workbenchRequests=['legacy'];},{},/replay state/);attempt((g,p)=>p.inventory.ferrite=60,{},/room/);});
test('save reload and reconnect preserve workbench progress sequence without duplicate output or offline catch-up',()=>{const{g,p}=setup();p.inventory.meat=1;p.inventory.fiber=1;g.world.structures.push({id:'bench',type:'workbench',x:0,z:3,rotation:0,owner:p.id,workbenchQueue:[],workbenchNextSequence:0});assert.equal(g.action(p.id,{type:'workbench',id:'bench',recipe:'ration',sequence:0}).ok,true);g.tick(2);const dir=fs.mkdtempSync(path.join(os.tmpdir(),'vibe-workbench-'));try{const file=path.join(dir,'world.json');saveWorld(file,g.world);const restored=new Game(loadWorld(file,999)),restoredPlayer=restored.join(p.id,p.name);assert.equal(restored.world.version,1);assert.equal(restored.world.time,g.world.time);assert.equal(restoredPlayer.inventory.ration,0);assert.equal(restored.world.structures[0].workbenchNextSequence,1);restored.tick(2.99);assert.equal(restoredPlayer.inventory.ration,0);restored.tick(.01);assert.equal(restoredPlayer.inventory.ration,1);restored.leave(p.id);restored.join(p.id,p.name);restored.tick(10);assert.equal(restoredPlayer.inventory.ration,1);assert.equal(restored.snapshot(p.id).structures[0].cycleUntil,1);}finally{fs.rmSync(dir,{recursive:true});}});
test('save reload and reconnect preserve cancelled queue truth and refunded ingredients',()=>{const{g,p}=setup(),q=g.join('other-explorer','Bo'),bench={id:'bench',type:'workbench',x:0,z:3,owner:p.id,workbenchGrants:[q.id],workbenchQueue:[],workbenchNextSequence:0};p.inventory.meat=1;p.inventory.fiber=1;q.inventory.meat=1;q.inventory.fiber=1;g.world.structures.push(bench);assert.equal(g.action(p.id,{type:'workbench',id:bench.id,recipe:'ration',sequence:0}).ok,true);assert.equal(g.action(q.id,{type:'workbench',id:bench.id,recipe:'ration',sequence:1}).ok,true);assert.equal(g.action(q.id,{type:'workbenchCancel',id:bench.id,jobId:'workbench-1'}).ok,true);g.tick(2);const dir=fs.mkdtempSync(path.join(os.tmpdir(),'vibe-workbench-cancel-'));try{const file=path.join(dir,'world.json');saveWorld(file,g.world);const restored=new Game(loadWorld(file,999)),restoredPlayer=restored.join(q.id,q.name),restoredBench=restored.world.structures[0];assert.equal(restored.world.version,1);assert.deepEqual(restoredBench.workbenchQueue.map(job=>job.id),['workbench-0']);assert.equal(restoredBench.workbenchNextSequence,2);assert.equal(restoredPlayer.inventory.meat,1);assert.equal(restoredPlayer.inventory.fiber,1);assert.equal(restored.action(q.id,{type:'workbench',id:restoredBench.id,recipe:'ration',sequence:2}).ok,true);assert.deepEqual(restoredBench.workbenchQueue.map(job=>job.id),['workbench-0','workbench-2']);restored.leave(q.id);restored.join(q.id,q.name);assert.equal(restored.snapshot(q.id).structures[0].workbenchCancelJobId,'workbench-2');}finally{fs.rmSync(dir,{recursive:true});}});
test('workbench rejects the first accepted request for its lifetime after more than 32 completions save reload and reconnect',()=>{const{g,p}=setup(),bench={id:'bench',type:'workbench',x:0,z:3,rotation:0,owner:p.id,workbenchQueue:[],workbenchRequests:[]};g.world.structures.push(bench);const request=sequence=>Object.hasOwn(g.snapshot(p.id).structures[0],'cycleUntil')?{type:'workbench',id:'bench',recipe:'ration',sequence}:{type:'workbench',id:'bench',recipe:'ration',requestId:`request-${sequence}`},first=request(0);for(let sequence=0;sequence<33;sequence++){p.inventory.meat=1;p.inventory.fiber=1;assert.equal(g.action(p.id,request(sequence)).ok,true);g.tick(5);assert.equal(p.inventory.ration,1);p.inventory.ration=0;}const dir=fs.mkdtempSync(path.join(os.tmpdir(),'vibe-workbench-lifetime-'));try{const file=path.join(dir,'world.json');saveWorld(file,g.world);const restored=new Game(loadWorld(file,999));restored.leave(p.id);const restoredPlayer=restored.join(p.id,p.name);restoredPlayer.inventory.meat=1;restoredPlayer.inventory.fiber=1;const before=structuredClone(restored.world);assert.equal(restored.action(p.id,first).ok,false);assert.deepEqual(restored.world,before);}finally{fs.rmSync(dir,{recursive:true});}});
test('server places a Deck stair on each of four supported deck edges',()=>{for(let rotation=0;rotation<4;rotation++){const{g,p}=setup();p.x=12;p.z=4.5;p.inventory.ferrite=10;p.inventory.fiber=10;g.world.resources=[];g.world.structures.push({id:'deck',type:'floor',x:12,z:0,rotation:0,owner:p.id});const result=g.action(p.id,{type:'build',piece:'stairs',x:12,z:0,rotation});assert.deepEqual(result,{ok:true,message:'Deck stair constructed.'});assert.deepEqual(g.world.structures.at(-1),{type:'stairs',x:12,z:0,rotation,health:200,id:'s1',owner:p.id});}});
test('Deck stairs conflict with every incompatible structure on the same physical edge',()=>{for(const type of['stairs','wall','doorway','door','airlock','perimeter']){const{g,p}=setup();p.x=9;p.z=4.5;g.world.structures.push({id:'deck',type:'floor',x:9,z:0,rotation:0,owner:p.id},{id:'edge',type,x:9,z:0,rotation:1,owner:p.id});assert.match(placementError(g.world,p,{type:'stairs',x:9,z:0,rotation:1}),/edge is occupied/,type);}const{g,p}=setup();p.x=9;p.z=4.5;g.world.structures.push({id:'deck',type:'floor',x:9,z:0,rotation:0,owner:p.id},{id:'neighbor-edge',type:'wall',x:12,z:0,rotation:3,owner:p.id});assert.match(placementError(g.world,p,{type:'stairs',x:9,z:0,rotation:1}),/edge is occupied/);});
test('Deck stairs reject structures intersecting their footprint before payment or mutation',()=>{for(const occupied of[[{id:'outward-deck',type:'floor',x:12,z:0,rotation:0}],[{id:'crossing-support',type:'floor',x:12,z:3,rotation:0},{id:'crossing-stair',type:'stairs',x:12,z:3,rotation:0}]]){const{g,p}=setup();p.x=9;p.z=4.5;p.inventory.ferrite=10;p.inventory.fiber=10;g.world.resources=[];g.world.structures.push({id:'deck',type:'floor',x:9,z:0,rotation:0,owner:p.id},...occupied);const before=structuredClone(g.world);const result=g.action(p.id,{type:'build',piece:'stairs',x:9,z:0,rotation:1});assert.match(result.message,/stair path is occupied/);assert.deepEqual(g.world,before);}});
test('Deck stair footprint rejects a later intersecting deck before payment or mutation',()=>{const{g,p}=setup();p.x=12;p.z=4.5;p.inventory.ferrite=10;p.inventory.fiber=10;g.world.resources=[];g.world.structures.push({id:'deck',type:'floor',x:12,z:0,rotation:0,owner:p.id});assert.equal(g.action(p.id,{type:'build',piece:'stairs',x:12,z:0,rotation:1}).ok,true);g.tick(1);const before={structures:structuredClone(g.world.structures),inventory:structuredClone(p.inventory),nextStructure:g.world.nextStructure};const result=g.action(p.id,{type:'build',piece:'floor',x:15,z:0,rotation:0});assert.match(result.message,/stair path is occupied/);assert.deepEqual(g.world.structures,before.structures);assert.deepEqual(p.inventory,before.inventory);assert.equal(g.world.nextStructure,before.nextStructure);});
test('Deck stair requests fail closed for missing support malformed grids range cost cap players and resources',()=>{const attempt=({prepare=()=>{},overrides={},message})=>{const{g,p}=setup();p.x=9;p.z=4.5;prepare(g,p);const before={structures:structuredClone(g.world.structures),inventory:structuredClone(p.inventory),nextStructure:g.world.nextStructure};const result=g.action(p.id,{type:'build',piece:'stairs',x:9,z:0,rotation:0,...overrides});assert.match(result.message,message);assert.deepEqual(g.world.structures,before.structures);assert.deepEqual(p.inventory,before.inventory);assert.equal(g.world.nextStructure,before.nextStructure);};attempt({message:/deck/});attempt({prepare:g=>g.world.structures.push({id:'deck',type:'floor',x:9,z:0,rotation:0}),overrides:{rotation:1.5},message:/Invalid placement/});attempt({prepare:g=>g.world.structures.push({id:'deck',type:'floor',x:9,z:0,rotation:0}),overrides:{site:{face:7,i:0,j:0},gx:0,gz:0},message:/Invalid local construction grid/});attempt({prepare:(g,p)=>{g.world.structures.push({id:'deck',type:'floor',x:9,z:0,rotation:0});p.x=30;},message:/closer/});attempt({prepare:g=>g.world.structures.push({id:'deck',type:'floor',x:9,z:0,rotation:0}),message:/resources/});attempt({prepare:(g,p)=>{p.inventory.ferrite=10;p.inventory.fiber=10;g.world.structures=Array.from({length:5000},(_,i)=>({id:`s${i}`,type:i===0?'floor':'perimeter',x:i===0?9:30+i*3,z:0,rotation:0}));},message:/structure limit/});attempt({prepare:(g,p)=>{p.inventory.ferrite=10;p.inventory.fiber=10;g.world.structures.push({id:'deck',type:'floor',x:9,z:0,rotation:0});const q=g.join('other-explorer','Bo');q.x=9;q.z=-2.25;},message:/player is in the way/});attempt({prepare:(g,p)=>{p.inventory.ferrite=10;p.inventory.fiber=10;g.world.structures.push({id:'deck',type:'floor',x:9,z:0,rotation:0});g.world.resources.push({id:'stair-resource',type:'ferrite',x:9,z:-2.25,amount:1});},message:/resources on the stair path/});});
test('Deck stair surface rises monotonically from terrain to exact deck height in all four rotations',()=>{for(let rotation=0;rotation<4;rotation++){const world=makeWorld(),deck={id:'deck',type:'floor',x:9,z:0,rotation:0},stairs={id:'stairs',type:'stairs',x:9,z:0,rotation};world.structures.push(deck,stairs);const[outX,outZ]=[[0,-1],[1,0],[0,1],[-1,0]][rotation],samples=[3,2.625,2.25,1.875,1.5].map(along=>({x:9+outX*along,z:outZ*along})),outerY=height(samples[0].x,samples[0].z,world.seed),innerY=floorHeight(deck,samples.at(-1),world.seed),lifts=samples.map((point,index)=>{const terrain=height(point.x,point.z,world.seed),expected=outerY+(innerY-outerY)*(index/4);assert.ok(Math.abs(surface(world,point.x,point.z)-expected)<1e-8,`rotation ${rotation} sample ${index}`);assert.equal(blocked(world,point.x,point.z),false);return surface(world,point.x,point.z)-terrain;});for(let i=1;i<lifts.length;i++)assert.ok(lifts[i]>lifts[i-1],`rotation ${rotation} lift ${i}`);const outside={x:9+outX*2.25-outZ,z:outZ*2.25+outX};assert.equal(surface(world,outside.x,outside.z),height(outside.x,outside.z,world.seed));assert.equal(surface(world,samples.at(-1).x,samples.at(-1).z),innerY);}});
