test('angled canopy rejects malformed unsupported remote unaffordable and capped requests before mutation',()=>{const attempt=({prepare=()=>{},message})=>{const{g,p}=setup();p.x=9;p.z=4.5;p.inventory.ferrite=10;p.inventory.fiber=10;prepare(g,p);const before={structures:structuredClone(g.world.structures),inventory:structuredClone(p.inventory),nextStructure:g.world.nextStructure};const result=g.action(p.id,{type:'build',piece:'angledCanopy',x:9,z:0,rotation:0});assert.match(result.message,message);assert.deepEqual(g.world.structures,before.structures);assert.deepEqual(p.inventory,before.inventory);assert.equal(g.world.nextStructure,before.nextStructure);};attempt({message:/deck/});attempt({prepare:(g,p)=>{g.world.structures.push({id:'deck',type:'floor',x:9,z:0,rotation:0,owner:p.id});p.x=30;},message:/closer/});attempt({prepare:(g,p)=>{g.world.structures.push({id:'deck',type:'floor',x:9,z:0,rotation:0,owner:p.id});p.inventory.fiber=0;},message:/resources/});attempt({prepare:(g,p)=>{g.world.structures=Array.from({length:5000},(_,i)=>({id:`s${i}`,type:i===0?'floor':'perimeter',x:i===0?9:30+i*3,z:0,rotation:0,owner:p.id}));},message:/structure limit/});const{g,p}=setup();p.x=9;p.z=4.5;p.inventory.ferrite=10;p.inventory.fiber=10;g.world.structures.push({id:'deck',type:'floor',x:9,z:0,rotation:0,owner:p.id});const before=structuredClone(g.world);assert.match(g.action(p.id,{type:'build',piece:'angledCanopy',x:9,z:0,rotation:1.5}).message,/Invalid placement/);assert.deepEqual(g.world,before);});
