test('shared depletion is atomic; no double gathering after last unit',()=>{const{g,p}=setup();const q=g.join('other-explorer','Bo'),n=g.world.resources[0];p.x=q.x=n.x;p.z=q.z=n.z;n.amount=1;assert.equal(g.action(p.id,{type:'gather',id:n.id}).ok,true);assert.equal(g.action(q.id,{type:'gather',id:n.id}).ok,false);assert.equal(p.inventory.ferrite+q.inventory.ferrite,1);});
test('Coral Shelf Flux gathering is authoritative depleted exactly once and survives save reload',()=>{const{g,p}=setup(),tile=tileAt(0,-1500),node=tileContent(g.world.seed,tile).nodes.find(node=>node.id.startsWith('p:coral:'));assert.ok(node);const before=structuredClone(g.world);assert.equal(g.action(p.id,{type:'gather',id:node.id}).ok,false);assert.deepEqual(g.world,before);Object.assign(p,{x:node.x,z:node.z});for(const key of Object.keys(p.inventory))p.inventory[key]=0;p.inventory.ferrite=60;assert.match(g.action(p.id,{type:'gather',id:node.id}).message,/Backpack full/);assert.equal(g.world.depleted[node.id],undefined);p.inventory.ferrite=0;assert.deepEqual(g.action(p.id,{type:'gather',id:node.id}),{ok:true,message:'+1 crystal'});assert.equal(p.inventory.crystal,1);assert.equal(g.world.depleted[node.id],node.amount-1);const firstSnapshot=g.snapshot(p.id),visible=firstSnapshot.resources.filter(resource=>resource.id===node.id);assert.equal(visible.length,1);assert.equal(visible[0].amount,node.amount-1);const after=structuredClone({inventory:p.inventory,depleted:g.world.depleted});assert.equal(g.action(p.id,{type:'gather',id:node.id}).ok,false);assert.deepEqual({inventory:p.inventory,depleted:g.world.depleted},after);const dir=fs.mkdtempSync(path.join(os.tmpdir(),'vibe-coral-resource-'));try{const file=path.join(dir,'world.json');saveWorld(file,g.world);const restored=new Game(loadWorld(file,999)),restoredPlayer=restored.join(p.id,p.name),restoredNode=restored.snapshot(p.id).resources.find(resource=>resource.id===node.id);assert.equal(restoredNode.amount,node.amount-1);assert.equal(restoredPlayer.inventory.crystal,1);assert.equal(restored.world.depleted[node.id],node.amount-1);}finally{fs.rmSync(dir,{recursive:true});}});
