test('open and closed sealed-door geometry matches collision in all four rotations',async()=>{const{doorParts,shape}=await import('../shared/world.js');for(let rotation=0;rotation<4;rotation++){const world=makeWorld(),door={id:`door-${rotation}`,type:'door',x:9,z:0,rotation,open:false};world.structures.push(door);const centre=shape(door,world.seed);assert.equal(blocked(world,centre.x,centre.z),true,`closed rotation ${rotation} blocks its edge`);door.open=true;assert.equal(blocked(world,centre.x,centre.z),false,`open rotation ${rotation} traverses its edge`);for(const part of doorParts(door,world.seed).filter(part=>part.kind!=='lintel')){const point=travel(centre,part.x,part.z);assert.equal(blocked(world,point.x,point.z),true,`open rotation ${rotation} ${part.kind} collides where rendered`);}}});
