test('malformed self duplicate prototype and non-owner grant requests fail closed',()=>{const{g,p}=setup();const q=g.join('other-explorer','Bo');g.world.structures.push({id:'s1',type:'floor',x:p.x,z:p.z,rotation:0,owner:p.id,dismantleGrants:[q.id]});const attempts=[[p.id,{type:'dismantleAccess',id:'s1',target:q.id,allow:true}],[p.id,{type:'dismantleAccess',id:'s1',target:p.id,allow:true}],[p.id,{type:'dismantleAccess',id:'s1',target:'__proto__',allow:true}],[p.id,{type:'dismantleAccess',id:'s1',target:'constructor',allow:true}],[p.id,{type:'dismantleAccess',id:'s1',target:'x'.repeat(129),allow:true}],[p.id,{type:'dismantleAccess',id:'s1',target:null,allow:true}],[p.id,{type:'dismantleAccess',id:'s1',target:q.id,allow:'yes'}],[q.id,{type:'dismantleAccess',id:'s1',target:p.id,allow:true}],[p.id,{type:'dismantleAccess',id:'missing',target:q.id,allow:true}]];for(const[actor,message]of attempts){const before=structuredClone(g.world.structures);assert.equal(g.action(actor,message).ok,false);assert.deepEqual(g.world.structures,before);}});
test('structure snapshots expose only viewer-specific dismantling authorization',()=>{const{g,p}=setup();const q=g.join('other-explorer','Bo'),r=g.join('third-explorer','Cy');g.world.structures.push({id:'s1',type:'floor',x:p.x,z:p.z,rotation:0,owner:p.id,dismantleGrants:[q.id]});const owner=g.snapshot(p.id).structures[0],collaborator=g.snapshot(q.id).structures[0],stranger=g.snapshot(r.id).structures[0],publicStructure=g.snapshot().structures[0];assert.deepEqual(owner.dismantleGrantedTo,[q.id]);assert.equal(owner.canDismantle,true);assert.equal(collaborator.canDismantle,true);for(const projected of[collaborator,stranger,publicStructure])assert.equal(Object.hasOwn(projected,'dismantleGrantedTo'),false);for(const projected of[stranger,publicStructure])assert.equal(Object.hasOwn(projected,'canDismantle'),false);for(const projected of[owner,collaborator,stranger,publicStructure])assert.equal(Object.hasOwn(projected,'dismantleGrants'),false);assert.deepEqual(g.world.structures[0].dismantleGrants,[q.id]);});
