test('saved prototype-key dismantling grants reveal no rejected values and authorize nobody',()=>{for(const forbidden of['__proto__','prototype','constructor']){const{g,p}=setup();Object.defineProperty(g.world.players,forbidden,{value:{...p,id:forbidden,name:'Unsafe'},enumerable:true,writable:true,configurable:true});g.world.structures.push({id:'s1',type:'floor',x:p.x,z:p.z,rotation:0,owner:p.id,dismantleGrants:[forbidden]});const before=structuredClone(g.world.structures[0]),ownerView=g.snapshot(p.id).structures[0],targetView=g.snapshot(forbidden).structures[0];assert.deepEqual(ownerView.dismantleGrantedTo,[]);assert.equal(Object.hasOwn(targetView,'canDismantle'),false);assert.equal(g.action(forbidden,{type:'dismantle',id:'s1'}).ok,false);assert.deepEqual(g.world.structures[0],before);}});
test('over-cap saved dismantling grants authorize nobody and project no values',()=>{const{g,p}=setup(),targets=Array.from({length:DISMANTLE_GRANT_LIMIT+1},(_,i)=>g.join(`saved-${i}`,`Saved ${i}`));for(const target of targets){target.x=p.x;target.z=p.z;}g.world.structures.push({id:'s1',type:'floor',x:p.x,z:p.z,rotation:0,owner:p.id,dismantleGrants:targets.map(target=>target.id)});const before=structuredClone(g.world.structures[0]),ownerView=g.snapshot(p.id).structures[0],targetView=g.snapshot(targets[0].id).structures[0];assert.deepEqual(ownerView.dismantleGrantedTo,[]);assert.equal(Object.hasOwn(targetView,'canDismantle'),false);assert.equal(g.action(targets[0].id,{type:'dismantle',id:'s1'}).ok,false);assert.deepEqual(g.world.structures[0],before);});
test('authorized collaborators remain subject to distance dependency locker capacity and cooldown protections',()=>{const{g,p}=setup();const q=g.join('other-explorer','Bo'),piece=(id,type='perimeter',x=0)=>({id,type,x,z:3,rotation:0,owner:p.id,dismantleGrants:[q.id]});q.x=0;q.z=3;g.world.structures.push(piece('far','perimeter',20));assert.equal(g.action(q.id,{type:'dismantle',id:'far'}).ok,false);g.world.structures.push(piece('deck','floor'),{id:'roof',type:'roof',x:0,z:3,rotation:0,owner:p.id});assert.equal(g.action(q.id,{type:'dismantle',id:'deck'}).ok,false);g.world.structures=g.world.structures.filter(s=>!['deck','roof'].includes(s.id));q.inventory.ferrite=60;g.world.structures.push(piece('full'));assert.equal(g.action(q.id,{type:'dismantle',id:'full'}).ok,false);q.inventory.ferrite=0;g.world.structures.push(piece('locker','cargo'));g.world.containers.locker={};p.x=0;p.z=3;assert.equal(g.action(p.id,{type:'lock',mode:'set',id:'locker',pin:'2468'}).ok,true);assert.equal(g.action(q.id,{type:'dismantle',id:'locker'}).ok,false);g.world.structures.push(piece('first'),piece('second'));assert.equal(g.action(q.id,{type:'dismantle',id:'first'}).ok,true);assert.match(g.action(q.id,{type:'dismantle',id:'second'}).message,/Tool cycling/);});
test('atomic save restores seed, depleted nodes, structures, progression and time',()=>{const{g,p}=setup();p.cutter=true;p.unlocked=true;p.inventory.fiber=7;p.x=11;g.world.resources[0].amount=0;g.world.structures.push({id:'s1',type:'floor',x:9,z:0,rotation:0,owner:p.id});g.world.nextStructure=2;g.tick(5);const dir=fs.mkdtempSync(path.join(os.tmpdir(),'vibe-save-'));try{const file=path.join(dir,'world.json');saveWorld(file,g.world);const restored=loadWorld(file,999);assert.deepEqual(restored,g.world);assert.equal(fs.existsSync(file+'.tmp'),false);fs.writeFileSync(file,'broken');assert.throws(()=>loadWorld(file,999));}finally{fs.rmSync(dir,{recursive:true});}});
test('doorway persists unchanged and survives exact multiplayer snapshot delivery',()=>{const{g,p}=setup();g.world.structures.push({id:'s1',type:'doorway',x:9,z:0,rotation:2,health:200,owner:p.id});g.world.nextStructure=2;const dir=fs.mkdtempSync(path.join(os.tmpdir(),'vibe-doorway-'));try{const file=path.join(dir,'world.json');saveWorld(file,g.world);const restoredGame=new Game(loadWorld(file,999)),session=createSnapshotSession(restoredGame.snapshot(p.id));restoredGame.world.time+=.1;const packet=nextSnapshotPacket(session,restoredGame.snapshot(p.id));assert.deepEqual(restoredGame.world.structures,g.world.structures);assert.deepEqual(session.state.structures,restoredGame.snapshot(p.id).structures);assert.ok(packet.type==='state'||packet.type==='delta');}finally{fs.rmSync(dir,{recursive:true});}});
test('angled canopy persists at save version one and survives exact multiplayer snapshot delivery',()=>{const{g,p}=setup();g.world.structures.push({id:'s1',type:'angledCanopy',x:9,z:0,rotation:2,health:200,owner:p.id});g.world.nextStructure=2;const dir=fs.mkdtempSync(path.join(os.tmpdir(),'vibe-angled-canopy-'));try{const file=path.join(dir,'world.json');saveWorld(file,g.world);const restored=loadWorld(file,999);assert.equal(VERSION,1);assert.equal(restored.version,1);const restoredGame=new Game(restored),session=createSnapshotSession(restoredGame.snapshot(p.id));restoredGame.world.time+=.1;const packet=nextSnapshotPacket(session,restoredGame.snapshot(p.id));assert.deepEqual(restoredGame.world.structures,g.world.structures);assert.deepEqual(session.state.structures,restoredGame.snapshot(p.id).structures);assert.ok(packet.type==='state'||packet.type==='delta');}finally{fs.rmSync(dir,{recursive:true});}});
test('Deck stair inherits version-one persistence and exact snapshot reconnect delivery',()=>{const{g,p}=setup();g.world.structures.push({id:'s1',type:'stairs',x:9,z:0,rotation:3,health:200,owner:p.id});g.world.nextStructure=2;const dir=fs.mkdtempSync(path.join(os.tmpdir(),'vibe-deck-stair-'));try{const file=path.join(dir,'world.json');saveWorld(file,g.world);const restored=loadWorld(file,999);assert.equal(VERSION,1);assert.equal(restored.version,1);const restoredGame=new Game(restored),session=createSnapshotSession(restoredGame.snapshot(p.id));restoredGame.world.time+=.1;const packet=nextSnapshotPacket(session,restoredGame.snapshot(p.id));assert.deepEqual(restoredGame.world.structures,g.world.structures);assert.deepEqual(session.state.structures,restoredGame.snapshot(p.id).structures);assert.equal(session.state.structures[0].rotation,3);assert.ok(packet.type==='state'||packet.type==='delta');}finally{fs.rmSync(dir,{recursive:true});}});
test('open sealed door persists at save version one and survives exact multiplayer snapshot delivery',()=>{const{g,p}=setup();g.world.structures.push({id:'s1',type:'door',x:9,z:0,rotation:3,health:200,owner:p.id,open:true});g.world.nextStructure=2;const dir=fs.mkdtempSync(path.join(os.tmpdir(),'vibe-sealed-door-'));try{const file=path.join(dir,'world.json');saveWorld(file,g.world);const restored=loadWorld(file,999);assert.equal(VERSION,1);assert.equal(restored.version,1);const restoredGame=new Game(restored),session=createSnapshotSession(restoredGame.snapshot(p.id));restoredGame.world.time+=.1;const packet=nextSnapshotPacket(session,restoredGame.snapshot(p.id));assert.deepEqual(restoredGame.world.structures,g.world.structures);assert.deepEqual(session.state.structures,restoredGame.snapshot(p.id).structures);assert.equal(session.state.structures[0].open,true);assert.ok(packet.type==='state'||packet.type==='delta');}finally{fs.rmSync(dir,{recursive:true});}});
test('atomic saves preserve per-structure grants while legacy structures remain owner-only',()=>{const{g,p}=setup();const q=g.join('other-explorer','Bo');g.world.structures.push({id:'s1',type:'floor',x:p.x,z:p.z,rotation:0,owner:p.id,dismantleGrants:[q.id]},{id:'s2',type:'perimeter',x:p.x+3,z:p.z,rotation:0,owner:p.id});const dir=fs.mkdtempSync(path.join(os.tmpdir(),'vibe-grants-'));try{const file=path.join(dir,'world.json');saveWorld(file,g.world);const restoredGame=new Game(loadWorld(file,999));restoredGame.join(q.id,q.name);restoredGame.world.players[q.id].x=p.x;restoredGame.world.players[q.id].z=p.z;assert.deepEqual(restoredGame.world.structures[0].dismantleGrants,[q.id]);assert.equal(restoredGame.action(q.id,{type:'dismantle',id:'s1'}).ok,true);restoredGame.tick(1);assert.equal(restoredGame.action(q.id,{type:'dismantle',id:'s2'}).ok,false);}finally{fs.rmSync(dir,{recursive:true});}});

test('input sequences fail closed without mutating movement or acknowledgement',()=>{const{g,p}=setup();assert.equal(g.inputAck(p.id),null);assert.equal(g.input(p.id,{sequence:4,x:1,z:0}),true);assert.equal(g.inputAck(p.id),4);assert.deepEqual(g.inputs.get(p.id).x,1);for(const sequence of [4,3,-1,1.5,Number.MAX_SAFE_INTEGER+1,Infinity,undefined]){assert.equal(g.input(p.id,{sequence,x:-1,z:0}),false);assert.equal(g.inputAck(p.id),4);assert.equal(g.inputs.get(p.id).x,1);}});
